import json, re
from collections import OrderedDict

# Load data
with open('/root/DATA/products/CoachForce.json') as f:
    coach = json.load(f)
with open('/root/DATA/products/PersonalizeForce.json') as f:
    personalize = json.load(f)

# Q1: authors and key reviewers of Market Research Report for CoachForce
authors=[]
for doc in coach.get('documents', []):
    if doc.get('type') == 'Market Research Report':
        auth = doc.get('author')
        if auth and auth not in authors:
            authors.append(auth)

reviewers=[]
for mt in coach.get('meeting_transcripts', []):
    if mt.get('document_type') == 'Market Research Report':
        for pid in mt.get('participants', []) or []:
            if pid and pid not in reviewers:
                reviewers.append(pid)

q1_list = authors + [r for r in reviewers if r not in authors]

# Q2: team members who provided insights on strengths/weaknesses of competitor products
competitors = ['TailorAI','PersonaAI','SmartSuggest']
keywords = [
    'offers','has','provides','uses','features','weakness','weaknesses','strength','strengths',
    'struggle','limited','issues','learning curve','barrier','cost','complex','privacy','reliance',
    'integration','segmentation','predictive','dashboard','analytics','machine learning','a/b testing','real-time'
]
q2_list=[]
for item in personalize.get('slack', []):
    msg=item.get('Message', {})
    user=msg.get('User', {})
    text=user.get('text','') or ''
    text_l=text.lower()
    if any(c.lower() in text_l for c in competitors):
        if any(k in text_l for k in keywords):
            uid=user.get('userId')
            if uid and uid not in q2_list:
                q2_list.append(uid)

# Q3: demo URLs for competitor products
q3_list=[]
for item in personalize.get('slack', []):
    msg=item.get('Message', {})
    user=msg.get('User', {})
    text=user.get('text','') or ''
    text_l=text.lower()
    if 'demo' in text_l:
        for url in re.findall(r"https?://[^\s>]+", text):
            if any(domain in url for domain in ['personaai.com','smartsuggest.com','tailorai.com']):
                if url not in q3_list:
                    q3_list.append(url)

# token count heuristic

def token_count(items):
    if not items:
        return 0
    return len(' '.join(items).split())

output = OrderedDict()
output['q1'] = {'answer': q1_list, 'tokens': str(token_count(q1_list))}
output['q2'] = {'answer': q2_list, 'tokens': str(token_count(q2_list))}
output['q3'] = {'answer': q3_list, 'tokens': str(token_count(q3_list))}

with open('/root/answer.json','w') as f:
    json.dump(output, f, indent=4)

print(json.dumps(output, indent=2))
